/**
 * Screening logic: income comparison and the deterministic criteria engine.
 *
 * Inlined into n8n Code nodes, so it stays dependency-free and avoids backticks
 * and template literals - those are consumed before the code reaches the node.
 *
 * NOTHING HERE CALLS A MODEL. The criteria engine reads manager-configured
 * thresholds and applies them identically to every applicant, which is what
 * HUD's May 2024 guidance describes when it says a screening tool should
 * "implement, rather than set" the housing provider's policies.
 *
 * It emits a classification and an evidence trail. It never emits a decision,
 * a score, a rank, or a recommendation - a human does that.
 */

/* --------------------------------------------------------------------- PII */

/**
 * An application form collects an SSN because a real one does. We keep the last
 * four and discard the rest on arrival; the raw value is never stored.
 */
function maskSsn(raw) {
  var digits = String(raw || "").replace(/\D/g, "");
  if (digits.length < 4) return null;
  return digits.slice(-4);
}

/* ------------------------------------------------------- Plaid normalisation */

var PERIODS_PER_YEAR = {
  WEEKLY: 52,
  BIWEEKLY: 26,
  SEMI_MONTHLY: 24,
  SEMIMONTHLY: 24,
  MONTHLY: 12,
  ANNUALLY: 1,
  ANNUAL: 1,
};

function monthlyFromPeriod(amount, frequency) {
  var perYear = PERIODS_PER_YEAR[String(frequency || "").toUpperCase()];
  if (!perYear || !amount) return null;
  return Math.round((amount * perYear) / 12 * 100) / 100;
}

/**
 * Pulls verified monthly income out of a /credit/payroll_income/get response.
 *
 * Uses the most recent pay stub and its stated frequency rather than summing
 * year-to-date, because YTD in Sandbox is not a full year and would understate
 * the figure.
 */
function parsePlaidPayrollIncome(response) {
  var result = {
    verified_monthly_income: null,
    employer_name: null,
    pay_frequency: null,
    gross_per_period: null,
    pay_period_end: null,
    employee_name: null,
    source: "plaid_sandbox",
    warnings: [],
  };

  var items = (response && response.items) || [];
  var stub = null;
  var source = null;

  for (var i = 0; i < items.length && !stub; i++) {
    var sources = items[i].payroll_income || [];
    for (var j = 0; j < sources.length && !stub; j++) {
      var stubs = sources[j].pay_stubs || [];
      if (stubs.length) {
        source = sources[j];
        // Most recent period first.
        stub = stubs.slice().sort(function (a, b) {
          var ea = (a.pay_period_details || {}).end_date || "";
          var eb = (b.pay_period_details || {}).end_date || "";
          return eb.localeCompare(ea);
        })[0];
      }
    }
  }

  if (!stub) {
    result.warnings.push("no pay stubs in the Plaid response");
    return result;
  }

  var details = stub.pay_period_details || {};
  result.employer_name = (source && source.employer && source.employer.name) || null;
  result.employee_name = (stub.employee && stub.employee.name) || null;
  result.pay_frequency = details.pay_frequency || null;
  result.gross_per_period = details.gross_earnings === undefined ? null : details.gross_earnings;
  result.pay_period_end = details.end_date || null;

  result.verified_monthly_income = monthlyFromPeriod(result.gross_per_period, result.pay_frequency);
  if (result.verified_monthly_income === null) {
    result.warnings.push("could not derive a monthly figure from gross " +
      result.gross_per_period + " at frequency " + result.pay_frequency);
  }

  return result;
}

/* ------------------------------------------------------- income comparison */

/**
 * The three numbers the demo puts side by side.
 *
 *   claimed   - what the applicant typed on the form
 *   extracted - what the model read off the uploaded pay stub
 *   verified  - what the bank actually shows
 *
 * A pay stub can be edited in a photo editor. A deposit history cannot. When
 * these disagree beyond tolerance the file is flagged for a human.
 */
function computeIncomeComparison(input) {
  var claimed = input.claimed === null || input.claimed === undefined ? null : Number(input.claimed);
  var extracted = input.extracted === null || input.extracted === undefined ? null : Number(input.extracted);
  var verified = input.verified === null || input.verified === undefined ? null : Number(input.verified);
  var tolerance = Number(input.tolerancePct === undefined ? 10 : input.tolerancePct);

  function variance(value) {
    if (value === null || verified === null || verified === 0) return null;
    return Math.round(Math.abs(value - verified) / verified * 1000) / 10;
  }

  var documentVariance = variance(extracted);
  var claimedVariance = variance(claimed);

  return {
    claimed_monthly: claimed,
    extracted_monthly: extracted,
    verified_monthly: verified,
    tolerance_pct: tolerance,
    document_variance_pct: documentVariance,
    claimed_variance_pct: claimedVariance,
    document_matches: documentVariance === null ? null : documentVariance <= tolerance,
    claimed_matches: claimedVariance === null ? null : claimedVariance <= tolerance,
    // The single fact the manager needs at a glance.
    mismatch_flagged:
      (documentVariance !== null && documentVariance > tolerance) ||
      (claimedVariance !== null && claimedVariance > tolerance),
  };
}

/* ---------------------------------------------------------- criteria engine */

function evidence(criterion, met, detail, source) {
  return { criterion: criterion, met: met, detail: detail, source: source || null };
}

/**
 * Applies the manager's published criteria.
 *
 * @returns {{result: string, evidence: Array, tenant_responsible_rent: number}}
 *   result is one of meets_criteria | conditional | does_not_meet.
 */
function runCriteriaEngine(input) {
  var app = input.application || {};
  var unit = input.unit || {};
  var config = input.config || {};
  var comparison = input.comparison || {};

  var incomeMultiple = Number(config.income_multiple || 3);
  var minCredit = Number(config.min_credit_score || 650);
  var conditionalCredit = Number(config.conditional_credit_min || 600);
  var maxEvictions = Number(config.max_eviction_filings || 0);

  var rent = Number(unit.rent_amount || 0);
  var assistance = Number(app.rental_assistance_amount || 0);

  // The income multiple applies to the tenant's share of rent, not gross rent.
  // Requiring a voucher holder to earn 3x the FULL rent is treated as
  // source-of-income discrimination in the jurisdictions that protect it.
  var tenantRent = Math.max(rent - assistance, 0);

  var trail = [];
  var verified = comparison.verified_monthly === undefined ? null : comparison.verified_monthly;

  /* income multiple, against verified income only */
  if (verified === null || !tenantRent) {
    trail.push(evidence("income_multiple", null,
      "cannot evaluate: verified income or rent is missing", null));
  } else {
    var ratio = Math.round(verified / tenantRent * 100) / 100;
    var detail = "$" + verified + "/mo verified against $" + tenantRent +
      " tenant-responsible rent = " + ratio.toFixed(2) + "x, threshold " +
      incomeMultiple.toFixed(2) + "x";
    if (assistance > 0) {
      detail += " (rent $" + rent + " less $" + assistance + " rental assistance)";
    }
    trail.push(evidence("income_multiple", ratio >= incomeMultiple, detail, {
      document: "plaid_payroll_income",
      field: "verified_monthly_income",
      value: verified,
    }));
  }

  /* documented income vs verified income */
  if (comparison.document_matches === null || comparison.document_matches === undefined) {
    trail.push(evidence("income_document_match", null,
      "cannot evaluate: no extracted document income", null));
  } else {
    trail.push(evidence("income_document_match", comparison.document_matches,
      "pay stub implies $" + comparison.extracted_monthly + "/mo against $" +
        comparison.verified_monthly + "/mo verified, variance " +
        comparison.document_variance_pct + "% (tolerance " + comparison.tolerance_pct + "%)",
      { document: "uploaded_paystub", field: "gross_this_period", value: comparison.extracted_monthly }));
  }

  /* credit - mocked data, real threshold */
  var credit = app.credit_score === null || app.credit_score === undefined ? null : Number(app.credit_score);
  if (credit === null) {
    trail.push(evidence("credit_score", null, "cannot evaluate: no credit score", null));
  } else {
    trail.push(evidence("credit_score", credit >= minCredit,
      credit + " against a " + minCredit + " threshold" +
        (credit < minCredit && credit >= conditionalCredit
          ? ", within the " + conditionalCredit + "-" + (minCredit - 1) + " conditional band"
          : ""),
      { document: "screening_bureau_mock", field: "credit_score", value: credit }));
  }

  /* eviction filings - mocked data, real threshold */
  var evictions = app.eviction_filings === null || app.eviction_filings === undefined
    ? null : Number(app.eviction_filings);
  if (evictions === null) {
    trail.push(evidence("eviction_history", null, "cannot evaluate: no eviction data", null));
  } else {
    trail.push(evidence("eviction_history", evictions <= maxEvictions,
      evictions + " filing(s) in the last " + (config.eviction_lookback_years || 5) +
        " years, maximum " + maxEvictions,
      { document: "screening_bureau_mock", field: "eviction_filings", value: evictions }));
  }

  /* identity - mocked */
  if (app.identity_match === null || app.identity_match === undefined) {
    trail.push(evidence("identity_check", null, "cannot evaluate: no identity result", null));
  } else {
    trail.push(evidence("identity_check", Boolean(app.identity_match),
      app.identity_match ? "document and applicant details matched" : "identity did not match",
      { document: "identity_check_mock", field: "match", value: app.identity_match }));
  }

  /* ------------------------------------------------------------ outcome */

  var failed = trail.filter(function (e) { return e.met === false; });
  var unknown = trail.filter(function (e) { return e.met === null; });

  var result;
  if (failed.length === 0 && unknown.length === 0) {
    result = "meets_criteria";
  } else if (failed.length === 0) {
    // Nothing failed, but something could not be evaluated. That is a human's
    // call, not a pass.
    result = "conditional";
  } else {
    var onlyCreditInBand =
      failed.length === 1 &&
      failed[0].criterion === "credit_score" &&
      credit !== null &&
      credit >= conditionalCredit;
    result = onlyCreditInBand ? "conditional" : "does_not_meet";
  }

  return {
    result: result,
    evidence: trail,
    tenant_responsible_rent: tenantRent,
    failed_criteria: failed.map(function (e) { return e.criterion; }),
    unevaluated_criteria: unknown.map(function (e) { return e.criterion; }),
    evaluated_at: new Date().toISOString(),
  };
}

/**
 * What a real FCRA adverse-action process would require. Shown to the manager
 * on the stop path so the demo makes the point explicitly.
 *
 * This build never generates any of these documents.
 */
function adverseActionRequirements() {
  return [
    "Pre-adverse-action notice, including a copy of the consumer report",
    "A copy of the FCRA Summary of Rights",
    "A waiting period for the applicant to dispute (commonly five business days)",
    "A final adverse-action notice naming the bureau that supplied the report",
  ];
}

/**
 * Shared front-of-funnel logic.
 *
 * This file is the single source of truth for lead parsing, reference tokens,
 * Tier A guardrails, and the pre-qualification gate. The build scripts inline it
 * into n8n Code nodes, so it must stay dependency-free and must not use
 * backticks or template literals - those are consumed before reaching the node.
 *
 * Nothing here calls a model. Everything here is deterministic.
 */

/* ------------------------------------------------------------------ tokens */

/**
 * Reference token carried in every subject line. Replies are matched on this
 * first and on sender address only as a fallback - the model never decides
 * which lead a message belongs to.
 */
function makeRefToken(prefix, seed) {
  var n = seed === undefined ? Math.floor(Math.random() * 9000) + 1000 : seed;
  return prefix + "-" + String(n).slice(0, 4);
}

function extractRefToken(text) {
  if (!text) return null;
  var match = String(text).match(/\[([RA]-\d{4})\]/);
  return match ? match[1] : null;
}

function subjectWithToken(subject, token) {
  if (extractRefToken(subject)) return subject;
  return subject + " [" + token + "]";
}

/* ------------------------------------------------------- lead email parsing */

/**
 * Parses a listing-site lead notification.
 *
 * Zillow delivers these as email with an anonymised relay reply-to and no phone
 * number, so the parser must tolerate a missing phone rather than treat it as a
 * failure. Anything it cannot determine is left null and flagged, never guessed.
 */
function parseLeadEmail(input) {
  var subject = input.subject || "";
  var body = input.body || "";
  var replyTo = input.replyTo || input.from || "";

  var result = {
    prospect_name: null,
    prospect_email: null,
    prospect_phone: null,
    unit_hint: null,
    inquiry_text: null,
    source: "zillow_email",
    parse_warnings: [],
  };

  var nameMatch = body.match(/^\s*Renter:\s*(.+)$/m);
  if (nameMatch) result.prospect_name = nameMatch[1].trim();
  else result.parse_warnings.push("no renter name found");

  var propertyMatch = body.match(/^\s*Property:\s*(.+)$/m);
  if (propertyMatch) result.unit_hint = propertyMatch[1].trim();
  else {
    var subjectUnit = subject.match(/:\s*(.+)$/);
    if (subjectUnit) result.unit_hint = subjectUnit[1].trim();
    else result.parse_warnings.push("no property reference found");
  }

  // The renter's own words, between the quotes after "Message:".
  var messageMatch = body.match(/Message:\s*"([\s\S]*?)"/);
  if (messageMatch) result.inquiry_text = messageMatch[1].replace(/\s+/g, " ").trim();
  else result.parse_warnings.push("no inquiry text found");

  var emailMatch = String(replyTo).match(/[\w.+-]+@[\w.-]+\.\w+/);
  if (emailMatch) result.prospect_email = emailMatch[0];
  else result.parse_warnings.push("no reply address found");

  var phoneMatch = body.match(/(\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}/);
  if (phoneMatch) result.prospect_phone = phoneMatch[0].trim();

  return result;
}

/* ------------------------------------------------- unit knowledge for the AI */

/**
 * Flattens a unit row into the only facts the FAQ model is allowed to use.
 * If a fact is not in here, the correct answer is "I don't have that".
 */
function buildUnitKnowledge(unit) {
  if (!unit) return null;
  var facts = unit.faq_facts || {};
  var knowledge = {
    unit_code: unit.unit_code,
    address: unit.address,
    bedrooms: unit.beds,
    bathrooms: Number(unit.baths),
    square_feet: unit.sqft,
    monthly_rent: Number(unit.rent_amount),
    security_deposit: Number(unit.deposit_amount),
    available_from: unit.available_from,
    lease_term_months: unit.lease_term_months,
    pet_policy: unit.pet_policy,
    pet_fee_monthly: unit.pet_fee_monthly === null ? null : Number(unit.pet_fee_monthly),
    parking: unit.parking,
    utilities: unit.utilities_included,
    laundry: unit.laundry,
  };
  Object.keys(facts).forEach(function (key) {
    knowledge[key] = facts[key];
  });
  return knowledge;
}

/* -------------------------------------------------------------- guardrails */

/**
 * Tier A guardrail. Runs on every message before it leaves, and again at send
 * time, because a manager may have edited the wording after it was drafted.
 *
 * Blocks: protected-class content, legal or lease commitments, rent negotiation,
 * availability promises, and invented numbers that are not in the unit facts.
 */
var PROTECTED_CLASS_PATTERNS = [
  { pattern: /\b(kids?|children|child|family friendly|families|school district)\b/i, label: "familial status" },
  { pattern: /\b(disab|wheelchair|handicap|mental health|service animal policy)\b/i, label: "disability" },
  { pattern: /\b(race|ethnic|nationality|immigration|citizen|visa status)\b/i, label: "national origin / race" },
  { pattern: /\b(church|mosque|temple|synagogue|religio)\b/i, label: "religion" },
  { pattern: /\b(marital status|married|single people|couples only)\b/i, label: "marital status" },
  { pattern: /\b(section 8|voucher|housing assistance|welfare)\b/i, label: "source of income" },
  { pattern: /\b(good neighborhood for|safe area for|type of people)\b/i, label: "steering" },
];

var COMMITMENT_PATTERNS = [
  { pattern: /\b(guarantee|guaranteed|we promise|you will be approved|pre-?approved)\b/i, label: "approval commitment" },
  { pattern: /\b(hold (it|the unit) for you|reserved for you|it'?s yours)\b/i, label: "availability commitment" },
  { pattern: /\b(we can lower|discount the rent|negotiate the rent|reduce the rent)\b/i, label: "rent negotiation" },
  { pattern: /\b(legally|by law|you are entitled|your rights under)\b/i, label: "legal statement" },
  { pattern: /\b(denied|rejected|you do not qualify|we cannot rent to you)\b/i, label: "adverse decision language" },
];

function guardrailCheck(text, knowledge) {
  var findings = [];
  var body = String(text || "");

  PROTECTED_CLASS_PATTERNS.forEach(function (rule) {
    if (rule.pattern.test(body)) {
      findings.push({ severity: "block", category: "protected_class", detail: rule.label });
    }
  });

  COMMITMENT_PATTERNS.forEach(function (rule) {
    if (rule.pattern.test(body)) {
      findings.push({ severity: "block", category: "commitment", detail: rule.label });
    }
  });

  // Any dollar figure in the message must appear in the unit facts. Catches the
  // model inventing a rent, fee, or deposit.
  if (knowledge) {
    var allowed = [];
    Object.keys(knowledge).forEach(function (key) {
      var value = knowledge[key];
      if (typeof value === "number") allowed.push(Math.round(value));
      if (typeof value === "string") {
        var found = value.match(/\d[\d,]*(\.\d+)?/g) || [];
        found.forEach(function (n) { allowed.push(Math.round(Number(n.replace(/,/g, "")))); });
      }
    });

    var quoted = body.match(/\$\s?\d[\d,]*(\.\d+)?/g) || [];
    quoted.forEach(function (raw) {
      var amount = Math.round(Number(raw.replace(/[$,\s]/g, "")));
      if (allowed.indexOf(amount) === -1) {
        findings.push({
          severity: "block",
          category: "unsupported_figure",
          detail: raw.trim() + " is not in the unit facts",
        });
      }
    });
  }

  var blocking = findings.filter(function (f) { return f.severity === "block"; });
  return {
    passed: blocking.length === 0,
    findings: findings,
    checked_at: new Date().toISOString(),
  };
}

/* ------------------------------------------------------- pre-qualification */

/**
 * Scheduling triage only. This is NOT a rental decision and its output must
 * never be phrased to a prospect as a denial.
 *
 * Deliberately narrow: move-in timing, self-reported income against the
 * published multiple, pet policy, and occupancy. Nothing else is considered and
 * nothing here is verified.
 */
function prequalGate(answers, unit, config) {
  var reasons = [];
  var missing = [];
  var incomeMultiple = config && config.income_multiple ? Number(config.income_multiple) : 3;

  if (!answers || answers.move_in_date === null || answers.move_in_date === undefined) {
    missing.push("move_in_date");
  } else {
    var availableFrom = new Date(unit.available_from);
    var wanted = new Date(answers.move_in_date);
    var daysAfter = (wanted - availableFrom) / 86400000;

    if (daysAfter < -14) {
      reasons.push({
        criterion: "move_in_timing",
        met: false,
        detail: "wants " + answers.move_in_date + ", unit is available from " + unit.available_from,
      });
    } else if (daysAfter > 60) {
      reasons.push({
        criterion: "move_in_timing",
        met: false,
        detail: "move-in is more than 60 days after the unit is available",
      });
    } else {
      reasons.push({ criterion: "move_in_timing", met: true, detail: answers.move_in_date });
    }
  }

  if (answers && (answers.stated_monthly_income === null || answers.stated_monthly_income === undefined)) {
    missing.push("stated_monthly_income");
  } else if (answers) {
    // Self-reported and unverified. Verification happens after an application.
    var rent = Number(unit.rent_amount);
    var stated = Number(answers.stated_monthly_income);
    var ratio = stated / rent;
    reasons.push({
      criterion: "stated_income",
      met: ratio >= incomeMultiple,
      detail: "$" + stated + "/mo stated against $" + rent + " rent = " + ratio.toFixed(2) + "x (unverified)",
    });
  }

  if (answers && answers.pets && String(answers.pets).toLowerCase() !== "none") {
    var weightMatch = String(answers.pets).match(/(\d+)\s?(lb|pound)/i);
    var overLimit = weightMatch && Number(weightMatch[1]) > 50;
    reasons.push({
      criterion: "pets",
      met: !overLimit,
      detail: overLimit ? "stated pet is over the 50 lb limit" : String(answers.pets),
    });
  }

  var failed = reasons.filter(function (r) { return r.met === false; });
  var result = missing.length ? "incomplete" : failed.length ? "not_clear" : "clear";

  return {
    result: result,
    reasons: reasons,
    missing: missing,
    evaluated_at: new Date().toISOString(),
  };
}

/* ------------------------------------------------------- AI output shape */

/**
 * Unwraps structured output from the OpenAI node.
 *
 * The payload arrives wrapped differently depending on node version, whether
 * simplify is on, and whether a JSON schema was applied - sometimes a parsed
 * object, sometimes a JSON string under `output`, sometimes nested one level
 * deeper. Probing for a known key is more robust than assuming a shape.
 *
 * @param {*} data       the item's json
 * @param {string} anchor a key that must exist on the real payload
 */
function unwrapAiPayload(data, anchor) {
  var value = data;

  for (var depth = 0; depth < 6; depth++) {
    if (value === null || value === undefined) break;

    if (typeof value === "string") {
      var trimmed = value.trim();
      if (trimmed.charAt(0) !== "{" && trimmed.charAt(0) !== "[") break;
      try {
        value = JSON.parse(trimmed);
      } catch (error) {
        break;
      }
      continue;
    }

    if (Array.isArray(value)) {
      value = value[0];
      continue;
    }

    if (typeof value === "object") {
      if (Object.prototype.hasOwnProperty.call(value, anchor)) return value;

      var next =
        value.output !== undefined ? value.output :
        value.message !== undefined ? value.message :
        value.content !== undefined ? value.content :
        value.text !== undefined ? value.text :
        value.json !== undefined ? value.json : undefined;

      if (next === undefined) break;
      value = next;
      continue;
    }

    break;
  }

  return value;
}

/* ------------------------------------------------------------- lock code */

/**
 * Self-guided tour entry code.
 *
 * MOCK. A real deployment issues this through a smart-lock platform
 * (Rently, Tour24, ButterflyMX) bound to the booking window. Here it is
 * generated locally and logged, and every record it touches is marked
 * source: "mock".
 */
function generateLockCode() {
  var code = String(Math.floor(Math.random() * 900000) + 100000);
  return { code: code, source: "mock", issued_at: new Date().toISOString() };
}

// Normalises the submitted form and discards the raw SSN immediately.
const out = [];
for (const item of $input.all()) {
  const form = item.json;

  // Form Trigger field keys can arrive generically, so read defensively.
  function field(names, fallback) {
    for (const name of names) {
      if (form[name] !== undefined && form[name] !== '') return form[name];
    }
    return fallback === undefined ? null : fallback;
  }

  function toNumber(value) {
    if (value === null || value === undefined || value === '') return null;
    const n = Number(String(value).replace(/[^0-9.\-]/g, ''));
    return Number.isFinite(n) ? n : null;
  }

  // The raw SSN is reduced to its last four digits here and never stored.
  const ssnLast4 = maskSsn(field(['ssn', 'SSN', 'Social Security Number']));

  const refToken = extractRefToken(String(field(['ref_token', 'Reference Code'], '')));

  out.push({
    json: {
      lead_ref_token: refToken,
      application_ref_token: makeRefToken('A'),
      full_name: field(['full_name', 'Full Name']),
      email: field(['email', 'Email']),
      phone: field(['phone', 'Phone']),
      ssn_last4: ssnLast4,
      current_address: field(['current_address', 'Current Address']),
      prior_address: field(['prior_address', 'Prior Address']),
      desired_move_in: field(['desired_move_in', 'Desired Move-In Date']),
      employer_name: field(['employer_name', 'Employer']),
      job_title: field(['job_title', 'Job Title']),
      claimed_monthly_income: toNumber(field(['claimed_monthly_income', 'Gross Monthly Income'])),
      rental_assistance_amount: toNumber(field(['rental_assistance_amount', 'Monthly Rental Assistance'])) || 0,
      occupants: toNumber(field(['occupants', 'Adults Living There'])),
      pets: field(['pets', 'Pets'], 'none'),
      vehicles: field(['vehicles', 'Vehicles'], 'none'),
      disclosures: {
        prior_eviction_filing: String(field(['prior_eviction', 'Prior Eviction Filing'], 'No')) === 'Yes',
        broken_lease: String(field(['broken_lease', 'Broken Lease'], 'No')) === 'Yes',
        bankruptcy_7_years: String(field(['bankruptcy', 'Bankruptcy In Last 7 Years'], 'No')) === 'Yes',
      },
      fcra_consent: true,
      unit_code: field(['unit_code', 'Unit'], 'MAPLE-2B'),
    },
    // Re-key the upload to a stable name. The Form Trigger names the binary
    // after the submitted field (field-N), not the field label, so the
    // downstream Extract node cannot rely on a fixed key otherwise.
    binary: (function () {
      const incoming = item.binary || {};
      const keys = Object.keys(incoming);
      if (!keys.length) return {};
      const pdfKey = keys.find(function (k) {
        const mime = (incoming[k] || {}).mimeType || '';
        return mime.indexOf('pdf') !== -1;
      }) || keys[0];
      return { paystub: incoming[pdfKey] };
    })(),
  });
}
return out;

